export const QUIET_SECONDS=1.5;
export function scheduleHorizon(project){const times=[0];for(const o of project.objects){if(o.virtual)continue;for(const k of o.keys||[])times.push(k.time);if(o.releaseTime!=null)times.push(o.releaseTime);}for(const g of project.groups||[])if(g.releaseTime!=null)times.push(g.releaseTime);for(const e of project.events)times.push(e.time,e.kind==='force'&&!e.continuous?e.time+e.duration:e.time);for(const e of project.explosions||[])times.push(e.time+1);for(const f of project.fields||[]){times.push(f.time);if(!f.continuous)times.push(f.time+f.duration);for(const k of f.keys||[])times.push(k.time);}return times.reduce((latest,t)=>Math.max(latest,t),0);}
export function ongoingMotion(project,time){if((project.fields||[]).some(f=>time>=f.time&&(f.continuous||time<f.time+f.duration)))return '작동 중인 기류·흡인';if(project.events.some(e=>e.kind==='force'&&time>=e.time&&(e.continuous||time<e.time+e.duration)))return '작동 중인 지속 힘';if((project.connections||[]).some(c=>['spring','hinge'].includes(c.kind)))return '진동·회전이 계속되는 연결';if(project.objects.some(o=>o.magnet?.polarity&&o.magnet.polarity!=='off'))return '자성에 의한 움직임';return '물체가 계속 움직임';}
